/**
 * THE PAPERS THAT MADE LYMPHOMA A SET OF DISEASES RATHER THAN ONE: the cell-of-origin work and the
 * immunohistochemical shortcut that carried it into practice, the three genetic classifications and the tool
 * that made them usable on one patient's tumour, the marker that splits follicular lymphoma in two, circulating
 * tumour DNA, the two viruses, and the Dutch and international cohorts that measured what curing Hodgkin
 * lymphoma costs decades later. Facet C of the lymphoma deep dive.
 *
 * Metadata verbatim from Europe PMC, read 1 October 2026; every figure comes from the indexed abstract of the
 * record named by the PubMed id. Two records (Burkitt 1958, Epstein 1964) have no indexed abstract, which is
 * stated on the record, and no number is quoted from either.
 *
 * Records the corpus already holds are linked by id and supplemented in ./lymphoma-evidence.ts rather than
 * repeated: paper-alizadeh-nature (Alizadeh 2000, the original cell-of-origin paper), paper-cheson-j-clin-oncol
 * (the Lugano classification), paper-kurtz-j-clin-oncol (circulating tumour DNA as an early outcome predictor in
 * diffuse large B-cell lymphoma) and paper-kurtz-nat-biotechnol (phased variants).
 */
type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, tags: ["lymphoma-evidence"], ...x });

